import React from 'react';
import { Card, Space, Typography, Divider, Tag, Alert } from 'antd';
import { 
  PermissionGate, 
  PlatformGate, 
  usePermissions, 
  usePlatform 
} from '../hooks/usePermissions';
import PermissionButton from '../components/PermissionButton';
import {
  LockOutlined,
  UnlockOutlined,
  CrownOutlined,
  UserOutlined,
  ToolOutlined,
  MobileOutlined,
  DesktopOutlined,
} from '@ant-design/icons';

const { Title, Text, Paragraph } = Typography;

const PermissionDemo: React.FC = () => {
  const { state, hasPermission, hasRole } = usePermissions();
  const { platform, isMiniApp, isWeb } = usePlatform();

  return (
    <div style={{ padding: 'var(--sp-spacing-sm)', maxWidth: 1200, margin: '0 auto', boxSizing: 'border-box' }}>
      <Title level={2}>
        Демонстрация системы полномочий и платформ
      </Title>
      
      <Paragraph>
        Эта страница демонстрирует работу системы полномочий (RBAC) и 
        адаптацию интерфейса для разных платформ (веб/мини-апп).
      </Paragraph>

      {/* Информация о текущем пользователе */}
      <Card 
        title={
          <Space>
            <UserOutlined />
            Информация о пользователе
          </Space>
        }
        style={{ marginBottom: 'var(--sp-spacing-sm)' }}
      >
        <Space direction="vertical" style={{ width: '100%' }}>
          <div>
            <Text strong>Платформа: </Text>
            <Tag 
              icon={isMiniApp ? <MobileOutlined /> : <DesktopOutlined />}
              color={isMiniApp ? 'blue' : 'green'}
            >
              {isMiniApp ? 'Telegram Mini App' : 'Веб-версия'}
            </Tag>
          </div>
          
          <div>
            <Text strong>Роли: </Text>
            {state.roles.length > 0 ? (
              <Space wrap>
                {state.roles.map(role => (
                  <Tag 
                    key={role.id} 
                    color={role.name === 'architect' ? 'gold' : 'blue'}
                    icon={role.name === 'architect' ? <CrownOutlined /> : <UserOutlined />}
                  >
                    {role.name}
                  </Tag>
                ))}
              </Space>
            ) : (
              <Text type="secondary">Роли не загружены</Text>
            )}
          </div>
          
          <div>
            <Text strong>Права: </Text>
            {state.permissions.length > 0 ? (
              <Space wrap>
                {state.permissions.slice(0, 5).map(permission => (
                  <Tag key={permission} color="green">
                    {permission}
                  </Tag>
                ))}
                {state.permissions.length > 5 && (
                  <Tag>+{state.permissions.length - 5} еще</Tag>
                )}
              </Space>
            ) : (
              <Text type="secondary">Права не загружены</Text>
            )}
          </div>
        </Space>
      </Card>

      {/* Демонстрация условного рендеринга по ролям */}
      <Card 
        title={
          <Space>
            <LockOutlined />
            Условный рендеринг по ролям
          </Space>
        }
        style={{ marginBottom: 'var(--sp-spacing-sm)' }}
      >
        <Space direction="vertical" style={{ width: '100%' }}>
          <PermissionGate 
            role="basic"
            fallback={<Alert message="Нет базовой роли" type="warning" />}
          >
            <Alert 
              message="Базовый пользователь" 
              description="Этот блок видят все пользователи с ролью 'basic' или выше"
              type="success" 
            />
          </PermissionGate>

          <PermissionGate 
            role="premium"
            fallback={<Alert message="Требуется Premium подписка" type="info" />}
          >
            <Alert 
              message="Premium функции" 
              description="Этот блок доступен только Premium пользователям"
              type="success" 
            />
          </PermissionGate>

          <PermissionGate 
            role="architect"
            fallback={<Alert message="Только для архитекторов" type="error" />}
          >
            <Alert 
              message="Панель архитектора" 
              description="Этот блок видят только архитекторы системы"
              type="success"
              icon={<CrownOutlined />}
            />
          </PermissionGate>
        </Space>
      </Card>

      {/* Демонстрация условного рендеринга по правам */}
      <Card 
        title={
          <Space>
            <UnlockOutlined />
            Условный рендеринг по правам
          </Space>
        }
        style={{ marginBottom: 'var(--sp-spacing-sm)' }}
      >
        <Space direction="vertical" style={{ width: '100%' }}>
          <PermissionGate 
            permission="api.keywords.read"
            fallback={<Alert message="Нет доступа к ключевым словам" type="warning" />}
          >
            <Alert 
              message="Доступ к ключевым словам" 
              description="У вас есть право 'api.keywords.read'"
              type="success" 
            />
          </PermissionGate>

          <PermissionGate 
            permission="api.reminders.write"
            fallback={<Alert message="Нет права создавать напоминания" type="warning" />}
          >
            <Alert 
              message="Создание напоминаний" 
              description="У вас есть право 'api.reminders.write'"
              type="success" 
            />
          </PermissionGate>
        </Space>
      </Card>

      {/* Демонстрация кнопок с проверкой прав */}
      <Card 
        title={
          <Space>
            <ToolOutlined />
            Кнопки с проверкой прав
          </Space>
        }
        style={{ marginBottom: 'var(--sp-spacing-sm)' }}
      >
        <Space wrap>
          <PermissionButton permission="api.keywords.read" type="primary">
            Читать ключевые слова
          </PermissionButton>
          
          <PermissionButton permission="api.reminders.write" type="default">
            Создать напоминание
          </PermissionButton>
          
          <PermissionButton role="premium" type="primary">
            Premium функция
          </PermissionButton>
          
          <PermissionButton role="architect" type="primary" danger>
            Панель архитектора
          </PermissionButton>
          
          <PermissionButton 
            permission="nonexistent.permission" 
            fallbackText="Нет доступа"
          >
            Недоступная функция
          </PermissionButton>
        </Space>
      </Card>

      {/* Демонстрация адаптации под платформу */}
      <Card 
        title={
          <Space>
            {isMiniApp ? <MobileOutlined /> : <DesktopOutlined />}
            Адаптация под платформу
          </Space>
        }
        style={{ marginBottom: 'var(--sp-spacing-sm)' }}
      >
        <Space direction="vertical" style={{ width: '100%' }}>
          <PlatformGate platform="miniapp">
            <Alert 
              message="Telegram Mini App" 
              description="Этот блок показывается только в мини-приложении Telegram"
              type="info"
              icon={<MobileOutlined />}
            />
          </PlatformGate>

          <PlatformGate platform="web">
            <Alert 
              message="Веб-версия" 
              description="Этот блок показывается только в веб-версии"
              type="success"
              icon={<DesktopOutlined />}
            />
          </PlatformGate>

          <Divider />
          
          <div>
            <Text strong>Текущая платформа: </Text>
            <Tag color={isMiniApp ? 'blue' : 'green'}>
              {platform}
            </Tag>
          </div>
          
          <div>
            <Text strong>Особенности интерфейса:</Text>
            <ul>
              {isMiniApp ? (
                <>
                  <li>Компактное горизонтальное меню внизу</li>
                  <li>Адаптированные размеры для мобильных устройств</li>
                  <li>Темная тема по умолчанию</li>
                  <li>Интеграция с Telegram WebApp API</li>
                </>
              ) : (
                <>
                  <li>Полноценное боковое меню</li>
                  <li>Расширенные возможности интерфейса</li>
                  <li>Поддержка различных тем</li>
                  <li>Веб-аутентификация</li>
                </>
              )}
            </ul>
          </div>
        </Space>
      </Card>

      {/* Информация о лимитах */}
      {state.limits && Object.keys(state.limits).length > 0 && (
        <Card 
          title="Лимиты пользователя"
          style={{ marginBottom: 'var(--sp-spacing-sm)' }}
        >
          <Space direction="vertical" style={{ width: '100%' }}>
            {state.limits.daily_requests && (
              <div>
                <Text strong>Дневные запросы: </Text>
                <Tag color="blue">{state.limits.daily_requests}</Tag>
              </div>
            )}
            {state.limits.max_output_tokens && (
              <div>
                <Text strong>Максимум токенов: </Text>
                <Tag color="green">{state.limits.max_output_tokens}</Tag>
              </div>
            )}
          </Space>
        </Card>
      )}

      {/* Состояние загрузки */}
      {state.loading && (
        <Alert 
          message="Загрузка полномочий..." 
          type="info" 
          style={{ marginBottom: 'var(--sp-spacing-sm)' }}
        />
      )}

      {/* Ошибки */}
      {state.error && (
        <Alert 
          message="Ошибка загрузки полномочий" 
          description={state.error}
          type="error" 
          style={{ marginBottom: 'var(--sp-spacing-sm)' }}
        />
      )}
    </div>
  );
};

export default PermissionDemo;
